import { defineScript, gezel } from '@bendyline/gezel-sdk';

export const meta = defineScript({
  name: 'ship-mock-probe',
  description:
    'Probe the live fake GitHub/CI services for this eval: opens the fake PR for branch chore/packing-count-export and polls CI for run pr-42. Outputs the raw JSON responses for the ship report.',
  inputs: {},
  outputs: {
    pr: { type: 'string', description: 'Raw JSON body from the fake GitHub PR creation.' },
    ci: { type: 'string', description: 'Raw JSON body from the fake CI status poll.' },
  },
  requires: ['workspace.read', 'network', 'credential:mock.github', 'credential:mock.ci'],
});

const services = JSON.parse(await gezel.fs.read('mocks/services.json'));
const base = (id) => {
  const service = services.find((entry) => entry.id === id);
  if (!service) throw new Error(`mock service "${id}" is not listed in mocks/services.json`);
  return service.baseUrl;
};

const pr = await gezel.http.authed(`${base('github')}/repos/co-op/returns-desk/pulls`, {
  credential: 'mock.github',
  method: 'POST',
  body: JSON.stringify({ branch: 'chore/packing-count-export', title: 'Packing count export' }),
});
if (!pr.ok) throw new Error(`fake GitHub PR creation failed: ${pr.status} ${pr.body}`);

const ci = await gezel.http.authed(`${base('ci')}/runs/pr-42`, { credential: 'mock.ci' });
if (!ci.ok) throw new Error(`fake CI poll failed: ${ci.status} ${ci.body}`);

gezel.output({ pr: pr.body, ci: ci.body });
